/// Prefisso di `s` lungo al massimo `max_bytes`, troncato su un boundary di
/// carattere UTF-8 valido. Sostituisce `&s[..n]` che PANICA se `n` cade in
/// mezzo a un carattere multibyte (es. accenti italiani à/è/é/ò/ù). Il panic
/// avveniva in un `tokio::spawn` detached → silenzioso, e bloccava l'intera
/// ingestione KB (M12.1) per ogni run con final_answer > 2000 byte.
fn safe_byte_prefix(s: &str, max_bytes: usize) -> &str {
    if s.len() <= max_bytes {
        return s;
    }
    let mut end = max_bytes;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
}

